import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  const width = 4.0;
  const height = 2.5;
  const segmentsX = 64;
  const segmentsY = 64;
  const displacementAmplitude = 0.18;
  const paddingLeft = 0.5;
  const baselineUnit = 0.25;

  // ============================================================================
  // MAIN IMAGE PLANE WITH DISPLACEMENT
  // ============================================================================

  const imageTexture = ctx.textureLoader.load(config.imageUrl);
  imageTexture.colorSpace = THREE.SRGBColorSpace;
  disposables.push(imageTexture);

  const depthTexture = ctx.textureLoader.load(config.depthMapUrl);
  depthTexture.colorSpace = THREE.LinearSRGBColorSpace;
  disposables.push(depthTexture);

  const geometry = new THREE.PlaneGeometry(width, height, segmentsX, segmentsY);
  disposables.push(geometry);

  const material = new THREE.MeshStandardMaterial({
    map: imageTexture,
    displacementMap: depthTexture,
    displacementScale: displacementAmplitude,
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 0,
  });
  disposables.push(material);

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // ============================================================================
  // TEXT CONTENT BLOCK
  // ============================================================================

  const textGroup = new THREE.Group();
  textGroup.position.z = 0.01;

  const textLines = [
    { text: 'NOVA ATELIER / GENEVA', size: 0.09 },
    { text: 'Time, Machined.', size: 0.34 },
    { text: 'Every case begins as a single billet of 904L steel.', size: 0.13 },
    { text: 'CALIBRE NA-01 / 72 HOUR RESERVE', size: 0.09 },
  ];

  let lineY = height / 2 - paddingLeft;

  for (const line of textLines) {
    const textMesh = ctx.fontAtlas.createText(line.text, {
      fontSize: line.size,
      color: new THREE.Color(0xe8ecf2),
    });

    if (textMesh) {
      textMesh.position.set(-width / 2 + paddingLeft, lineY, 0);
      textGroup.add(textMesh);
      lineY -= baselineUnit;
    }
  }

  group.add(textGroup);

  // ============================================================================
  // ACCENT HAIRLINE BAR (between headline and body)
  // ============================================================================

  const barGeo = new THREE.PlaneGeometry(0.75, 0.02);
  const barMat = new THREE.MeshStandardMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
  });
  const barMesh = new THREE.Mesh(barGeo, barMat);
  barMesh.position.z = 0.02;
  barMesh.position.x = -width / 2 + paddingLeft;
  barMesh.position.y = height / 2 - paddingLeft - baselineUnit * 1.5;
  group.add(barMesh);
  disposables.push(barGeo, barMat);

  // ============================================================================
  // SCRIM OVERLAY
  // ============================================================================

  const scrimGeo = new THREE.PlaneGeometry(width, height);
  const scrimMat = new THREE.MeshStandardMaterial({
    color: 0x0b0b10,
    transparent: true,
    opacity: 0.35,
  });
  const scrimMesh = new THREE.Mesh(scrimGeo, scrimMat);
  scrimMesh.position.z = 0.005;
  group.add(scrimMesh);
  disposables.push(scrimGeo, scrimMat);

  // ============================================================================
  // ANIMATIONS
  // ============================================================================

  // Plate opacity: 0 -> 1 over 500ms cubic-bezier(0.25,0.46,0.45,0.94)
  const plateTl = gsap.timeline();
  plateTl.to(material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(plateTl);

  // Caption block rise-in: y +0.4 -> 0 over 700ms starting 120ms after plate
  textGroup.position.y = 0.4;
  const captionTl = gsap.timeline();
  captionTl.to(
    textGroup.position,
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0.12,
  );
  timelines.push(captionTl);

  // ============================================================================
  // CINEMATIC PRIMITIVES
  // ============================================================================

  for (const prim of config.cinematicPrimitives || []) {
    if (ctx.primitives[prim.name]) {
      ctx.primitives[prim.name](plane, prim.params || {});
    }
  }

  // ============================================================================
  // CLEANUP
  // ============================================================================

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl?.kill?.());
    disposables.forEach((d) => d?.dispose?.());
  };

  group.userData.handlers = {};

  return group;
}
